"""
claude_code agents capability.

Implements the uniform agents contract (same surface every adapter exposes):

  list_agents()              -> list[dict]            # sidebar agents
  create_agent(body)         -> dict | JSONResponse   # POST /api/agents
  get_detail(agent_id)       -> dict | None           # None if not ours
  patch(agent_id, body)      -> resp | None            # None if not ours
  delete(agent_id)           -> resp | None            # None if not ours

claude_code agents are project folders under xo-projects; their record lives in
``<project>/.xo/agent.json`` (legacy: ``~/claude-cowork/<id>/.agent.json``,
read-only). The core router forwards here via ``load_capability('agents', …)``
instead of branching on ``backend == "claude_code"``.
"""
from __future__ import annotations

import json
from datetime import datetime, timezone
from pathlib import Path

from fastapi.responses import JSONResponse

from services.cowork_agent.helpers import normalize_agent_id
from services.cowork_agent.project_layout import (
    project_dir,
    scaffold_project,
    xo_dir,
    xo_projects_root,
)
from services.cowork_agent.registry.settings import CLAUDE_COWORK_DIR


# ── On-disk record helpers ────────────────────────────────────────────────────


def _meta_path(agent_id: str) -> Path:
    """Canonical write location: <project>/.xo/agent.json under xo-projects."""
    return xo_dir(agent_id) / "agent.json"


def _meta_legacy_path(agent_id: str) -> Path:
    """Pre-xo-projects location: ~/claude-cowork/<id>/.agent.json (read-only fallback)."""
    return CLAUDE_COWORK_DIR / agent_id / ".agent.json"


def _load(agent_id: str) -> dict | None:
    """Read .xo/agent.json; fall back to legacy ~/claude-cowork/<id>/.agent.json."""
    for path in (_meta_path(agent_id), _meta_legacy_path(agent_id)):
        if path.exists():
            try:
                return json.loads(path.read_text())
            except Exception:
                return None
    return None


def _write(agent_id: str, data: dict) -> None:
    """Always writes to the canonical xo-projects location."""
    path = _meta_path(agent_id)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(data, indent=2))


def _workspace_path(agent_id: str) -> Path:
    """Where the project lives on disk. Prefers xo-projects, falls back to legacy."""
    new_path = project_dir(agent_id)
    if (xo_dir(agent_id) / "agent.json").exists() or (xo_dir(agent_id) / "project.json").exists():
        return new_path
    legacy = CLAUDE_COWORK_DIR / agent_id
    if legacy.is_dir():
        return legacy
    return new_path


def _agent_info(agent_id: str, meta: dict) -> dict:
    workspace = str(_workspace_path(agent_id))
    return {
        "name": agent_id,
        "description": meta.get("description") or meta.get("name") or agent_id,
        "mode": "primary",
        "tools": [],
        "permissions": {"rules": []},
        "system_prompt": None,
        "temperature": None,
        "metadata": {
            "backend": "claude_code",
            "display_name": meta.get("name") or agent_id,
            "workspace": workspace,
        },
    }


# ── Uniform agents contract ───────────────────────────────────────────────────


def list_agents() -> list[dict]:
    """Sidebar agents: every xo-project dir that has a ``.xo/agent.json``."""
    agents: list[dict] = []
    projects_root = xo_projects_root()
    if projects_root.exists():
        for d in sorted(projects_root.iterdir()):
            if not d.is_dir() or d.name.startswith("."):
                continue
            meta_path = d / ".xo" / "agent.json"
            if not meta_path.exists():
                continue
            try:
                meta = json.loads(meta_path.read_text())
            except Exception:
                meta = {}
            agents.append(_agent_info(d.name, meta))
    return agents


def create_agent(body) -> dict | JSONResponse:
    """Create a claude_code agent: scaffold the project tree + write the record."""
    display_name = body.name.strip()
    agent_id = normalize_agent_id((body.id or body.name).strip())
    description = (body.description or "").strip()

    # Reject only if the claude_code agent record already exists. The project
    # folder being present is fine — multiple backends can attach to the same
    # xo-projects/<id>/ project.
    if _load(agent_id) is not None:
        return JSONResponse(
            status_code=409,
            content={"detail": f'Claude Code agent "{agent_id}" already exists.'},
        )

    try:
        scaffold_project(agent_id, display_name=display_name, description=description)
        meta = {
            "id": agent_id,
            "name": display_name,
            "description": description,
            "backend": "claude_code",
            "created_at": datetime.now(timezone.utc).isoformat(),
        }
        _write(agent_id, meta)
    except Exception as e:
        return JSONResponse(status_code=500, content={"detail": str(e)})

    return _agent_info(agent_id, meta)


def get_detail(agent_id: str) -> dict | None:
    """Full agent snapshot if ``agent_id`` is a claude_code agent, else None."""
    aid = normalize_agent_id(agent_id)
    meta = _load(aid)
    if meta is None:
        return None
    workspace_path = _workspace_path(aid)
    return {
        "id": aid,
        "display_name": (meta.get("name") or "").strip() or aid,
        "description": meta.get("description") or "",
        "workspace": str(workspace_path),
        "model": None,
        "model_raw": None,
        "identity": {"name": None, "emoji": None, "bio": None},
        "config_entry": {},
        "agents_defaults": {},
        "workspace_files": {},
        "on_disk": {
            "agent_dir": str(workspace_path),
            "models_catalog": None,
            "auth_state": None,
            "auth_profiles": None,
        },
        "sessions": {
            "index_path": str(workspace_path / ".sessions"),
            "count": 0,
            "session_ids": [],
        },
        "openclaw_global_auth": {},
        "backend": "claude_code",
    }


def patch(agent_id: str, body) -> dict | JSONResponse | None:
    """Patch a claude_code agent's name/description; None if not ours."""
    aid = normalize_agent_id(agent_id)
    if _load(aid) is None:
        return None
    if not body.model_fields_set:
        detail = get_detail(aid)
        return detail if detail else JSONResponse(status_code=404, content={"detail": "Not found"})
    meta = _load(aid) or {}
    if body.name is not None:
        meta["name"] = body.name.strip()
    if body.description is not None:
        meta["description"] = body.description.strip()
    _write(aid, meta)
    detail = get_detail(aid)
    return detail if detail else JSONResponse(status_code=500, content={"detail": "Failed to read agent after update"})


def delete(agent_id: str) -> dict | JSONResponse | None:
    """claude_code has no delete contract today."""
    return None

"""
Agent CRUD endpoints — thin forwarding to each backend's ``agents`` capability.

Dispatch (no backend is named here — everything resolves through
``load_capability("agents", …)``):

- ``GET  /api/agents``        → the ACTIVE backend's ``agents.list_agents()``
- ``POST /api/agents``        → ``agents.create_agent(body)`` for ``body.backend``
                                (defaults to the active agent when omitted)
- ``GET/PATCH/DELETE /api/agents/{id}`` → ownership resolution: try each
  installed adapter's ``agents`` capability in registry order; the first whose
  hook returns non-None handles the request.

The per-backend logic (openclaw.json mutation, hermes profile CLI, claude_code
project records) lives in ``adapters/<name>/agents.py``.
"""

from fastapi import APIRouter
from fastapi.responses import JSONResponse
from pydantic import BaseModel, Field

from services.cowork_agent.registry.agent_registry import get_active_agent
from services.cowork_agent.registry.adapter_registry import list_adapters
from services.cowork_agent.adapters.loader import try_load_capability
from services.cowork_agent.helpers import normalize_agent_id

router = APIRouter()


# ── Pydantic request bodies (shared request shapes; passed opaquely to adapters) ─


class CreateAgentBody(BaseModel):
    """Payload for POST /api/agents."""

    name: str = Field(..., min_length=1, max_length=200)
    id: str | None = Field(None, max_length=80)
    description: str | None = Field(None, max_length=4000)
    workspace: str | None = Field(None, max_length=2048)
    # Target backend; defaults to the active agent when omitted. Validated at
    # dispatch against the installed adapters (via load_capability), so no
    # backend name is hardcoded here.
    backend: str | None = Field(None, max_length=80)


class UpdateAgentBody(BaseModel):
    """PATCH /api/agents/{id} — only fields present in the JSON body are applied."""

    name: str | None = Field(None, max_length=200)
    description: str | None = Field(None, max_length=4000)
    workspace: str | None = Field(None, max_length=2048)
    model: str | None = Field(None, max_length=400)
    identity_name: str | None = Field(None, max_length=200)
    identity_emoji: str | None = Field(None, max_length=32)
    # Hermes-only today: writes to ``<profile>/SOUL.md``. OpenClaw uses
    # ``identity_*`` for the same role; claude_code doesn't take it.
    system_prompt: str | None = Field(None, max_length=64_000)


# ── Ownership resolution ──────────────────────────────────────────────────────


def get_agent_detail(agent_id: str) -> dict | None:
    """Full agent snapshot from whichever backend owns ``agent_id``.

    Tries each installed adapter's ``agents.get_detail`` in registry order and
    returns the first non-None result (an id is owned by one backend in
    practice). Returns None if no backend recognizes it.
    """
    for name in list_adapters():
        mod = try_load_capability("agents", agent=name)
        getter = getattr(mod, "get_detail", None) if mod else None
        if getter:
            detail = getter(agent_id)
            if detail is not None:
                return detail
    return None


# ── Routes ───────────────────────────────────────────────────────────────────


@router.get("/api/agents")
def list_agents():
    """Return the sidebar agents for the active backend (``AGENT_NAME`` env).

    Only the active backend's agents are surfaced; the others stay invisible —
    matching the user's mental model that ``AGENT_NAME`` decides which world
    we're in, so chats can't accidentally route through the wrong backend.
    """
    mod = try_load_capability("agents")
    if mod is None or not hasattr(mod, "list_agents"):
        return []
    return mod.list_agents()


@router.post("/api/agents")
def create_agent(body: CreateAgentBody):
    agent_id = normalize_agent_id((body.id or body.name).strip())
    if agent_id == "main":
        return JSONResponse(status_code=400, content={"detail": 'Agent id "main" is reserved; choose another id or name.'})

    backend = (body.backend or "").strip() or get_active_agent().name
    mod = try_load_capability("agents", agent=backend)
    if mod is None or not hasattr(mod, "create_agent"):
        return JSONResponse(status_code=400, content={"detail": f"Unknown or unsupported backend: {backend}"})
    return mod.create_agent(body)


@router.get("/api/agents/{agent_id}")
def get_agent(agent_id: str):
    detail = get_agent_detail(agent_id)
    if not detail:
        return JSONResponse(status_code=404, content={"detail": f'Agent "{agent_id}" not found'})
    return detail


@router.delete("/api/agents/{agent_id}")
def delete_agent(agent_id: str):
    """Delete an agent, resolved to whichever backend owns the id. Backends
    without a delete contract (openclaw / claude_code today) return None, so an
    unknown id falls through to a generic 404."""
    for name in list_adapters():
        mod = try_load_capability("agents", agent=name)
        deleter = getattr(mod, "delete", None) if mod else None
        if deleter:
            result = deleter(agent_id)
            if result is not None:
                return result
    return JSONResponse(
        status_code=404,
        content={"detail": f'Agent "{agent_id}" not found, or its backend has no delete contract.'},
    )


@router.patch("/api/agents/{agent_id}")
def patch_agent(agent_id: str, body: UpdateAgentBody):
    for name in list_adapters():
        mod = try_load_capability("agents", agent=name)
        patcher = getattr(mod, "patch", None) if mod else None
        if patcher:
            result = patcher(agent_id, body)
            if result is not None:
                return result
    return JSONResponse(status_code=404, content={"detail": f'Agent "{agent_id}" not found'})

"""GET /api/xo-projects — BFF list of user projects.

Sits on top of services/cowork_agent/project_layout helpers. Strips the
``path`` field so the frontend never sees absolute filesystem
locations; merges scaffolded and unscaffolded directories into one
sorted list (newest first) and marks each entry with ``unscaffolded``
so the UI can prompt to complete setup.

See docs/bff-endpoints-design.md §9.1 for the full contract.
"""

from __future__ import annotations

from datetime import datetime, timezone
from typing import Optional

from fastapi import APIRouter, HTTPException
from pydantic import BaseModel

from routers.cowork_agent.bff.filters import (
    PROJECT_SYSTEM_LEAVES,
    is_hidden_name,
    is_root_only_hidden,
)
from services.cowork_agent import scopes
from services.cowork_agent.project_layout import (
    list_project_tree,
    list_projects,
    list_unscaffolded_dirs,
    project_dir_exists,
)

router = APIRouter()


class Project(BaseModel):
    id: str
    display_name: str
    description: Optional[str] = None
    created_at: Optional[str] = None
    unscaffolded: bool


class ListProjectsResponse(BaseModel):
    items: list[Project]
    total: int


def _to_iso_utc(ts: Optional[float]) -> Optional[str]:
    if ts is None:
        return None
    return (
        datetime.fromtimestamp(ts, tz=timezone.utc)
        .isoformat()
        .replace("+00:00", "Z")
    )


def _shape_scaffolded(entry: dict) -> Project:
    name = str(entry.get("name") or "")
    display = entry.get("display_name") or name
    return Project(
        id=name,
        display_name=str(display),
        description=(entry.get("description") or None),
        created_at=(entry.get("created_at") or None),
        unscaffolded=False,
    )


def _shape_unscaffolded(entry: dict) -> Project:
    name = str(entry.get("name") or "")
    return Project(
        id=name,
        display_name=name,
        description=None,
        created_at=_to_iso_utc(entry.get("mtime")),
        unscaffolded=True,
    )


def _sort_newest_first(items: list[Project]) -> list[Project]:
    """Newest first by created_at; nulls last; alphabetical tiebreak."""
    with_ts = sorted(
        [p for p in items if p.created_at],
        key=lambda p: p.id,
    )
    with_ts.sort(key=lambda p: p.created_at or "", reverse=True)
    without_ts = sorted(
        [p for p in items if not p.created_at],
        key=lambda p: p.id,
    )
    return with_ts + without_ts


@router.get("/api/xo-projects", response_model=ListProjectsResponse)
def list_xo_projects() -> ListProjectsResponse:
    try:
        scopes.resolve_scope("xo-projects")  # validates scope exists
        scaffolded = list_projects()
        unscaffolded = list_unscaffolded_dirs()
    except OSError as exc:
        raise HTTPException(
            status_code=500,
            detail={
                "code": "scope_unavailable",
                "message": "Project directory is not readable.",
            },
        ) from exc

    items: list[Project] = []
    for entry in scaffolded:
        if (entry.get("name") or "") in PROJECT_SYSTEM_LEAVES:
            continue
        items.append(_shape_scaffolded(entry))
    for entry in unscaffolded:
        if (entry.get("name") or "") in PROJECT_SYSTEM_LEAVES:
            continue
        items.append(_shape_unscaffolded(entry))

    items = _sort_newest_first(items)
    return ListProjectsResponse(items=items, total=len(items))


# ── /api/xo-projects/{id}/tree ────────────────────────────────────────────────


class TreeEntry(BaseModel):
    name: str
    relative_path: str


class ProjectTreeResponse(BaseModel):
    project_id: str
    relative_path: str
    parent_relative_path: Optional[str] = None
    dirs: list[TreeEntry]
    files: list[TreeEntry]


def _filter_tree_entries(entries: list[dict], at_root: bool) -> list[TreeEntry]:
    out: list[TreeEntry] = []
    for e in entries:
        name = e.get("name") or ""
        if is_hidden_name(name):
            continue
        if at_root and is_root_only_hidden(name):
            continue
        out.append(TreeEntry(name=name, relative_path=e.get("relative_path") or ""))
    return out


@router.get("/api/xo-projects/{project_id}/tree", response_model=ProjectTreeResponse)
def project_tree(project_id: str, relative_path: str = "") -> ProjectTreeResponse:
    if not project_dir_exists(project_id):
        raise HTTPException(
            status_code=404,
            detail={"code": "project_not_found", "message": "Project not found."},
        )

    try:
        raw = list_project_tree(project_id, relative_path)
    except ValueError as exc:
        raise HTTPException(
            status_code=400,
            detail={
                "code": "invalid_relative_path",
                "message": "relative_path is malformed or escapes the project root.",
            },
        ) from exc
    except OSError as exc:
        raise HTTPException(
            status_code=500,
            detail={
                "code": "scope_unavailable",
                "message": "Project directory is not readable.",
            },
        ) from exc

    if raw is None:
        raise HTTPException(
            status_code=404,
            detail={"code": "directory_not_found", "message": "Directory not found in project."},
        )

    at_root = (raw["relative_path"] or "") == ""
    return ProjectTreeResponse(
        project_id=raw["project_id"],
        relative_path=raw["relative_path"],
        parent_relative_path=raw["parent_relative_path"],
        dirs=_filter_tree_entries(raw["dirs"], at_root),
        files=_filter_tree_entries(raw["files"], at_root),
    )

    if not isinstance(content, str):
        return JSONResponse(status_code=400, content={"detail": "Content must be a string"})

    base = Path.home()
    target = Path(raw_path).resolve()

    if not str(target).startswith(str(base)):
        return JSONResponse(status_code=403, content={"detail": "Access denied"})

    try:
        target.parent.mkdir(parents=True, exist_ok=True)
        data = content.encode("utf-8")
        target.write_bytes(data)
    except Exception as e:
        return JSONResponse(status_code=500, content={"detail": str(e)})

    return {"path": str(target), "bytes": len(data)}


@router.post("/api/files/mkdir")
async def make_directory(request: Request):
    """Create a new directory under the user's home directory.

    Body fields:
    - ``path`` (str, required): absolute path of the directory to create.
    - ``scaffold`` (bool, optional): when true, treats the target as a new
      project under ``xo-projects/`` and builds the canonical layout (see
      ``services.cowork_agent.project_layout``). The target's parent must
      resolve to ``xo_projects_root()``; otherwise the call is rejected.
    - ``display_name`` (str, optional): when scaffolding, sets the
      project's display name in ``.xo/project.json``. Falls back to the
      folder name.
    - ``description`` (str, optional): when scaffolding, sets the
      project's description in ``.xo/project.json``.
    - ``files`` (list[str], optional): additional local file paths to copy
      into the new directory. Each entry must be an absolute path that
      already exists under the user's home directory. Existing files with
      the same name are not overwritten.
    """
    body = await request.json()
    raw_path = body.get("path")
    scaffold = bool(body.get("scaffold", False))
    display_name = body.get("display_name")
    description = body.get("description")
    extra_files: list[str] = body.get("files") or []

    if not raw_path:
        return JSONResponse(status_code=400, content={"detail": "Missing path"})

    base = Path.home()
    target = Path(raw_path).resolve()

    if not str(target).startswith(str(base)):
        return JSONResponse(status_code=403, content={"detail": "Access denied"})

    if target.exists():
        return JSONResponse(status_code=409, content={"detail": "Already exists"})

    # Scaffold paths must land directly under xo-projects root.
    if scaffold:
        projects_root = xo_projects_root()
        if target.parent.resolve() != projects_root:
            return JSONResponse(
                status_code=400,
                content={
                    "detail": (
                        f"scaffold:true requires path to be a direct child of "
                        f"{projects_root}; got {target}"
                    )
                },
            )

    # Validate extra file paths before creating anything
    resolved_extras: list[Path] = []
    for raw_file in extra_files:
        fp = Path(raw_file).resolve()
        if not str(fp).startswith(str(base)):
            return JSONResponse(
                status_code=403,
                content={"detail": f"Access denied: {raw_file}"},
            )
        if not fp.is_file():
            return JSONResponse(
                status_code=404,
                content={"detail": f"File not found: {raw_file}"},
            )
        resolved_extras.append(fp)

    try:
        if scaffold:
            scaffold_project(
                target.name,
                display_name=(display_name.strip() if isinstance(display_name, str) else None),
                description=(description.strip() if isinstance(description, str) else None),
            )
            target = project_dir(target.name)
        else:
            target.mkdir(parents=True, exist_ok=False)

        copied = []
        for src in resolved_extras:
            dest = target / src.name
            if not dest.exists():
                shutil.copy2(src, dest)
            copied.append(src.name)
    except Exception as e:
        return JSONResponse(status_code=500, content={"detail": str(e)})

    return {"path": str(target), "name": target.name, "copied": copied}

# ── Read / list ───────────────────────────────────────────────────────────────


def load_project(name: str) -> dict | None:
    """Read .xo/project.json for an existing project, or None if absent."""
    path = project_metadata_path(normalize_agent_id(name))
    if not path.exists():
        return None
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
        return data if isinstance(data, dict) else None
    except Exception:
        return None


def project_exists(name: str) -> bool:
    """True iff the project folder has a .xo/project.json record."""
    return project_metadata_path(normalize_agent_id(name)).exists()


def list_projects() -> list[dict]:
    """Filesystem-driven project list. Backend-agnostic.

    Returns one dict per directory under xo-projects that has
    ``.xo/project.json``. Hidden directories are skipped. Missing or
    malformed metadata yields a minimal entry with just ``name`` and
    ``path`` so the UI can still surface the folder.
    """
    root = xo_projects_root()
    out: list[dict] = []
    if not root.exists():
        return out

    for entry in sorted(root.iterdir()):
        if not entry.is_dir() or entry.name.startswith("."):
            continue
        meta_path = entry / ".xo" / "project.json"
        if not meta_path.exists():
            continue
        try:
            meta = json.loads(meta_path.read_text(encoding="utf-8"))
        except Exception:
            meta = {}
        if not isinstance(meta, dict):
            meta = {}
        if not meta.get("name"):
            meta["name"] = entry.name
        if not meta.get("display_name"):
            meta["display_name"] = meta["name"]
        meta["path"] = str(entry)
        out.append(meta)

    return out


def project_dir_exists(name: str) -> bool:
    """True iff the project root directory exists (scaffolded or not)."""
    return project_dir(name).is_dir()

