        resolved_extras.append(fp)

    try:
        if scaffold:
            scaffold_project(
                target.name,
                display_name=(display_name.strip() if isinstance(display_name, str) else None),
                description=(description.strip() if isinstance(description, str) else None),
            )
            target = project_dir(target.name)
        else:
            target.mkdir(parents=True, exist_ok=False)

        copied = []
        for src in resolved_extras:
            dest = target / src.name
            if not dest.exists():
                shutil.copy2(src, dest)
            copied.append(src.name)
    except Exception as e:
        return JSONResponse(status_code=500, content={"detail": str(e)})

    if scaffold:
        return JSONResponse(
            status_code=201,
            content={"path": str(target), "name": target.name, "copied": copied},
            headers={"X-Created": "true"},
        )
    return {"path": str(target), "name": target.name, "copied": copied}
